import sys
import xml.etree.ElementTree as ET
import random
import string

def generate_access_code():
    return ''.join(random.choices(string.ascii_lowercase, k=32))

def main():
    if len(sys.argv) != 2:
        print("Usage: python make_invite_page.py guests.xml")
        return

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        print("Error: Invalid XML file")
        return

    guests = []
    for guest_elem in root.findall('guest'):
        name = guest_elem.get('name')
        email = guest_elem.get('email')
        if name and email:
            guests.append((name, email))

    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>Guest Access Codes</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <h1>Guest Access Codes</h1>
    <table>
        <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Access Code</th>
        </tr>
"""

    for name, email in guests:
        code = generate_access_code()
        html += f"""        <tr>
            <td>{name}</td>
            <td>{email}</td>
            <td>{code}</td>
        </tr>
"""

    html += """
    </table>
</body>
</html>
"""
    print(html)

if __name__ == "__main__":
    main()
